import{_ as e,o,c as a,a4 as u}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"1971年 · 多元版图初现","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1971年.md","filePath":"05_quotes/by-year/1971年.md"}'),l={name:"05_quotes/by-year/1971年.md"};function r(q,t,c,s,h,_){return o(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1971年-·-多元版图初现" tabindex="-1">1971年 · 多元版图初现 <a class="header-anchor" href="#_1971年-·-多元版图初现" aria-label="Permalink to &quot;1971年 · 多元版图初现&quot;">​</a></h1><blockquote><p>&quot;当整个行业在&#39;分享&#39;繁荣的时候，我们也分到了一杯羹。但我们意识到，这背后也存在隐忧。&quot;——巴菲特（40岁）</p></blockquote><p>本页收录1971年致股东信中的经典语录。伯克希尔剔除资本利得后营业收益超过期初股东权益14%，远超行业均值。巴菲特在信中首次系统性展现&quot;控股企业集群&quot;战略——保险、银行、零售各有明星掌门人，而&quot;宁要利润不要规模&quot;的理念已深入骨髓。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;当整个行业在&#39;分享&#39;繁荣的时候，我们也分到了一杯羹。但我们意识到，这背后也存在隐忧。&quot;</p></blockquote><blockquote><p>&quot;我们始终将承保盈利作为首要目标，这意味着1972年国民赔偿保险公司的直接保费规模很可能出现大幅下滑。&quot;</p></blockquote><blockquote><p>&quot;我们从未设定规模目标——在再保险业务中更是如此，因为只要放弃盈利标准，几乎任何规模的业务都能拿到。&quot;</p></blockquote><blockquote><p>&quot;三家公司的管理者均白手起家打造了自己的公司，在以现金出售全部股权后，依然完整保留着对公司一如既往的主人翁精神与自豪感。&quot;</p></blockquote><blockquote><p>&quot;我们的保险与银行子公司与公众之间存在受托责任关系。我们始终坚信，必须以极为稳健的财务状况开展经营，确保能够毫无异议地履行自身责任。&quot;</p></blockquote><blockquote><p>&quot;在大力压降成本、持续开发价格敏感度更低的面料品类之后，最终仅实现了微薄利润。但倘若没有这些努力，公司纺织业务将出现巨额亏损。&quot;</p></blockquote><blockquote><p>&quot;尽管存款结构中付息存款占比极高，但税后营业收益仍再次超过平均存款规模的2%。&quot;</p></blockquote><blockquote><p>&quot;管理层的长期目标是：在坚持稳健的会计政策与债务政策的前提下，实现长期平均资本回报率略高于美国工业企业的整体水平。&quot;</p></blockquote><blockquote><p>&quot;目前已有微弱迹象表明，部分竞争对手已意识到其费率水平（以及损失准备金）存在严重不足，这可能会在年内逐步缓解市场的恶性竞争压力。&quot;</p></blockquote><blockquote><p>&quot;我们已将资本从低回报业务向高回报业务转移，这一转型正在进行中，但进展速度取决于市场条件。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1971年是伯克希尔转型后的第二年。巴菲特完成了对芝加哥家庭与汽车保险公司的收购，保险版图持续扩张，银行保持行业领先盈利。但巴菲特在年报中冷静指出：当前的超额回报率&quot;从低基数提升容易，维持高位更难&quot;。同年，&quot;本土州&quot;保险模式（HomeState）在明尼苏达和德州开始复制，标志着他的保险扩张战略进入新阶段。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1971年-翻译-·-01-letters-1971年-核心总结" tabindex="-1"><a href="/01_letters/1971年/翻译">01_letters/1971年/翻译</a> · <a href="/01_letters/1971年/核心总结">01_letters/1971年/核心总结</a> <a class="header-anchor" href="#_01-letters-1971年-翻译-·-01-letters-1971年-核心总结" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1971年/翻译]] · [[→ 核心总结|01_letters/1971年/核心总结]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1971年/翻译">/01_letters/1971年/翻译</a></li></ul>',23)])])}const p=e(l,[["render",r]]);export{i as __pageData,p as default};
